const EXCLUDED = new Set(["XRP", "BTC", "USDT", "USDC", "PI"]);
const SCALE = 18;
const unwrapArray = <T,>(payload?: ApiEnvelope<T[]> | null) => Array.isArray(payload?.data) ? payload?.data as T[] : Array.isArray((payload?.data as { data?: T[] })?.data) ? ((payload?.data as { data?: T[] }).data || []) : [];
