const boolish = (value: unknown) => value === true || value === 1 || value === "1";
const providerStatusLabel = (status?: string | null) => ({ configuration_required: "Configuration required", provider_unavailable: "Provider unavailable", rpc_unavailable: "RPC unavailable", testnet_only: "Testnet only", maintenance: "Maintenance" } as Record<string, string>)[String(status || "").toLowerCase()] || (status ? String(status).replaceAll("_", " ") : "Awaiting sync");
const formatDate = (value?: string | null) => !value ? "Pending" : Number.isNaN(new Date(value).getTime()) ? "Pending" : new Intl.DateTimeFormat(undefined, { dateStyle: "medium" }).format(new Date(value));
const formatDateTime = (value?: string | null) => !value ? "Not confirmed" : Number.isNaN(new Date(value).getTime()) ? "Not confirmed" : new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
function toInt(value: string) { const negative = value.startsWith("-"); const normalized = negative ? value.slice(1) : value; if (!/^\d+(\.\d+)?$/.test(normalized)) return 0n; const [i, f = ""] = normalized.split("."); const total = BigInt(i || "0") * 10n ** BigInt(SCALE) + BigInt((f + "0".repeat(SCALE)).slice(0, SCALE)); return negative ? -total : total; }
function fromInt(value: bigint, precision = 8) { const negative = value < 0n; const abs = negative ? -value : value; const raw = abs.toString().padStart(SCALE + 1, "0"); const head = raw.slice(0, -SCALE) || "0"; const tail = raw.slice(-SCALE).slice(0, precision).replace(/0+$/, ""); const out = tail ? `${head}.${tail}` : head; return negative && out !== "0" ? `-${out}` : out; }
const cmp = (a: string, b: string) => toInt(a) === toInt(b) ? 0 : toInt(a) > toInt(b) ? 1 : -1;
const add = (a: string, b: string, p = 8) => fromInt(toInt(a) + toInt(b), p);
const sub = (a: string, b: string, p = 8) => { const v = toInt(a) - toInt(b); return v <= 0n ? "0" : fromInt(v, p); };
const mul = (a: string, b: string, p = 8) => fromInt((toInt(a) * toInt(b)) / 10n ** BigInt(SCALE), p);
const divInt = (a: string, d: number, p = 8) => d ? fromInt(toInt(a) / BigInt(d), p) : "0";
