    const authError = (value: unknown) => { const candidate = value as { status?: number; message?: string }; return candidate?.status === 401 || /authentication required/i.test(String(candidate?.message ?? "")); };
    const rejected = results.find((result, index) => result.status === "rejected" && !(catalogReady && [2, 3, 4, 7].includes(index) && authError(result.reason)));
    if (rejected && rejected.status === "rejected") setNotice(messageForError(rejected.reason)); else if (loaded.current) setNotice("");
    if (results[0].status === "fulfilled") setAssets(unwrapArray(results[0].value).filter((item) => !EXCLUDED.has(item.symbol.toUpperCase())));
    if (results[1].status === "fulfilled") setProducts(unwrapArray(results[1].value).filter((item) => !EXCLUDED.has(item.symbol.toUpperCase())));
    if (results[2].status === "fulfilled") setPortfolio(unwrapArray(results[2].value));
    if (results[3].status === "fulfilled") setPositions(unwrapArray(results[3].value).filter((item) => !EXCLUDED.has(item.symbol.toUpperCase())));
    if (results[4].status === "fulfilled") setRewards(unwrapArray(results[4].value).filter((item) => !EXCLUDED.has(item.symbol.toUpperCase())));
    if (results[5].status === "fulfilled") setCampaigns(unwrapArray(results[5].value));
    if (results[6].status === "fulfilled") setStatuses(unwrapArray(results[6].value).filter((item) => !EXCLUDED.has(item.symbol.toUpperCase())));
    if (results[7].status === "fulfilled") setBalances(unwrapArray(results[7].value));
